fn gcd(a: Int, b: Int) -> Int {
    let mut x = a
    let mut y = b
    while y != 0 {
        let temp = y
        y = x % y
        x = temp
    }
    x
}
fn main() {
    print(gcd(252, 105))
}

fn is_prime(n: Int) -> Bool {
    if n <= 1 { return false }
    for i in range(2, n) {
        if n % i == 0 { return false }
    }
    true
}
fn count_primes(limit: Int) -> Int {
    let mut count = 0
    for num in range(2, limit) {
        if is_prime(num) {
            count += 1
        }
    }
    count
}
fn main() {
    print(count_primes(100))
}

fn fib(n: Int) -> Int {
    let a = 1
    let b = 1
    for _ in range(0, n - 2) {
        let temp = a + b
        a = b
        b = temp
    }
    b
}
fn main() {
    print(fib(20))
}

